import java.applet.*;import java.awt.*;public abstract class Robot{	public static final int IMAGE = 10, MASK = IMAGE/2;	protected final int MOVE_BOT = 1;	private int last_y, last_x;		protected int y_location, x_location;		protected Goal your_goal;	protected Obstacle an_obstacle;	protected Applet applet;		public Robot(Applet this_applet, Obstacle this_obstacle, Goal this_goal,		int this_x, int this_y){			applet = this_applet;		an_obstacle = this_obstacle;		your_goal = this_goal;				x_location = this_x;		y_location = this_y;		last_x = this_x;		last_y = this_y;		}		abstract public void move();		public void draw(Graphics page){		page.drawRect(x_location, y_location, MASK, MASK);	}		public boolean stillSearching(){			return your_goal.goalFound(x_location, y_location);		}}